-- Period study v2; read-only; 2026-09-05 through 2026-09-11 Asia/Shanghai.
-- Observation frame uses ended lessons in the available daily partitions.
-- See report for snapshot, completeness and denominator limitations.
WITH frame AS (SELECT school_uid,COUNT(1) AS scheduled_n,SUM(CASE WHEN class_status=3 THEN 1 ELSE 0 END) AS opened_n,SUM(CASE WHEN class_status=4 THEN 1 ELSE 0 END) AS cancelled_n FROM eo_pdviews.ods_ms_eo_os_eeo_course_class_di_view WHERE dt>='2026-09-05' AND dt<='2026-09-11' AND class_btime>=1788537600 AND class_btime<1789142400 AND school_uid>0 GROUP BY school_uid HAVING SUM(CASE WHEN class_status=3 THEN 1 ELSE 0 END)>0), thresholds AS (SELECT percentile_approx(opened_n,0.3333333333) AS q1,percentile_approx(opened_n,0.6666666667) AS q2 FROM frame), strat AS (SELECT f.school_uid,f.scheduled_n,f.opened_n,f.cancelled_n,CASE WHEN f.opened_n<=t.q1 THEN 'low' WHEN f.opened_n<=t.q2 THEN 'mid' ELSE 'high' END AS stratum,t.q1,t.q2 FROM frame f CROSS JOIN thresholds t), pe AS (SELECT e.school_uid,e.course_id,e.activity_id,e.biz_type,e.action,e.uid,COUNT(1) AS n FROM eo_pdviews.dwd_acitive_user_lms_action_details_di_view e JOIN strat f ON e.school_uid=f.school_uid WHERE e.dt>='2026-09-05' AND e.dt<='2026-09-11' AND e.event_time>=1788537600 AND e.event_time<1789142400 AND e.role='student' AND e.action IN ('handin_homework','handin_exam','looked_activity') AND e.biz_type IN (2,3) GROUP BY e.school_uid,e.course_id,e.activity_id,e.biz_type,e.action,e.uid) SELECT e.biz_type,e.action,SUM(e.n) AS event_n,COUNT(1) AS student_activity_n,COUNT(DISTINCT e.activity_id) AS activity_n,COUNT(DISTINCT e.school_uid) AS institution_n FROM pe e JOIN eo_pdviews.ods_ms_eo_oslms_lms_activity_df_view a ON a.id=e.activity_id AND a.school_uid=e.school_uid AND a.course_id=e.course_id AND a.biz_type=e.biz_type WHERE a.dt='2026-09-11' AND a.is_deleted=0 AND a.publish_flag=2 AND a.biz_type IN (2,3) GROUP BY e.biz_type,e.action ORDER BY e.biz_type,e.action LIMIT 10;
